import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.2Gs1zKBA.js";const m=JSON.parse('{"title":"A1 机械臂参数","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/editions.md","filePath":"getting-started/editions.md","lastUpdated":1794555138000}'),a={name:"getting-started/editions.md"};function c(h,t,n,i,s,l){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="a1-机械臂参数" tabindex="-1">A1 机械臂参数 <a class="header-anchor" href="#a1-机械臂参数" aria-label="Permalink to &quot;A1 机械臂参数&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">参数与安全说明</p><p>实际使用前请以设备铭牌、出厂资料和现场安全评估为准。负载、运动范围和速度参数不是安全操作许可，真机运行前必须确认机械臂固定可靠、按手册要求设置隔离区域、工作区域无人员和障碍物，并确保供电可以随时切断。</p></div><h2 id="整机参数" tabindex="-1">整机参数 <a class="header-anchor" href="#整机参数" aria-label="Permalink to &quot;整机参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>数值</th></tr></thead><tbody><tr><td>产品名称</td><td>onero Robotic Arm A1</td></tr><tr><td>自由度</td><td>7 轴</td></tr><tr><td>单臂自重</td><td>4.3 kg</td></tr><tr><td>最大负载</td><td>3 kg</td></tr><tr><td>最大臂展</td><td>739.45 mm</td></tr><tr><td>重复定位精度</td><td>±0.1 mm</td></tr><tr><td>电源需求</td><td>DC 48 V；供电能力至少 6 A</td></tr><tr><td>通信接口</td><td>CAN 2.0，速率 1 Mbps</td></tr><tr><td>综合功率</td><td>&lt;300 W</td></tr><tr><td>控制模式</td><td>位置控制 + 力控</td></tr></tbody></table><h2 id="关节参数" tabindex="-1">关节参数 <a class="header-anchor" href="#关节参数" aria-label="Permalink to &quot;关节参数&quot;">​</a></h2><p>运动范围和扭矩保留产品说明书中的标称值，最大速度以当前 <code>onero-sdk</code> 的逐关节模型限值为准；A1R 与 A1L 的速度限值相同。</p><table tabindex="0"><thead><tr><th>关节</th><th>产品标称运动范围</th><th>SDK 最大速度</th><th>产品标称额定扭矩</th><th>产品标称最大扭矩</th></tr></thead><tbody><tr><td>J1</td><td>-60°～+180°</td><td>3.0 rad/s（约 171.9°/s）</td><td>15 N·m</td><td>30 N·m</td></tr><tr><td>J2</td><td>-180°～+15°</td><td>3.0 rad/s（约 171.9°/s）</td><td>15 N·m</td><td>30 N·m</td></tr><tr><td>J3</td><td>±158°</td><td>3.0 rad/s（约 171.9°/s）</td><td>15 N·m</td><td>30 N·m</td></tr><tr><td>J4</td><td>±110°</td><td>3.0 rad/s（约 171.9°/s）</td><td>15 N·m</td><td>30 N·m</td></tr><tr><td>J5</td><td>±158°</td><td>6.0 rad/s（约 343.8°/s）</td><td>3 N·m</td><td>7 N·m</td></tr><tr><td>J6</td><td>±90°</td><td>6.0 rad/s（约 343.8°/s）</td><td>3 N·m</td><td>7 N·m</td></tr><tr><td>J7</td><td>±158°</td><td>6.0 rad/s（约 343.8°/s）</td><td>3 N·m</td><td>7 N·m</td></tr></tbody></table><p>J1～J4 为大臂关节，J5～J7 为腕部关节。上述速度是 SDK 模型上限；如果 <code>SafetyConfig.max_velocity</code> 设置得更低，运行时还会进一步限速。产品标称运动范围不能直接替代 SDK 模型限位。</p><h2 id="sdk-模型关节位置限位" tabindex="-1">SDK 模型关节位置限位 <a class="header-anchor" href="#sdk-模型关节位置限位" aria-label="Permalink to &quot;SDK 模型关节位置限位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关节</th><th>A1R 运动范围（rad；约合角度）</th><th>A1L 运动范围（rad；约合角度）</th></tr></thead><tbody><tr><td>J1</td><td><code>-1.04～3.14</code>（约 <code>-59.6°～179.9°</code>）</td><td><code>-3.14～1.04</code>（约 <code>-179.9°～59.6°</code>）</td></tr><tr><td>J2</td><td><code>-3.14～0.26</code>（约 <code>-179.9°～14.9°</code>）</td><td><code>-0.26～3.14</code>（约 <code>-14.9°～179.9°</code>）</td></tr><tr><td>J3</td><td><code>-2.76～2.76</code>（约 <code>-158.1°～158.1°</code>）</td><td><code>-2.76～2.76</code>（约 <code>-158.1°～158.1°</code>）</td></tr><tr><td>J4</td><td><code>-1.92～1.92</code>（约 <code>-110.0°～110.0°</code>）</td><td><code>-1.92～1.92</code>（约 <code>-110.0°～110.0°</code>）</td></tr><tr><td>J5</td><td><code>-2.23～2.23</code>（约 <code>-127.8°～127.8°</code>）</td><td><code>-2.23～2.23</code>（约 <code>-127.8°～127.8°</code>）</td></tr><tr><td>J6</td><td><code>-1.57～1.57</code>（约 <code>-90.0°～90.0°</code>）</td><td><code>-1.57～1.57</code>（约 <code>-90.0°～90.0°</code>）</td></tr><tr><td>J7</td><td><code>-2.76～2.76</code>（约 <code>-158.1°～158.1°</code>）</td><td><code>-2.76～2.76</code>（约 <code>-158.1°～158.1°</code>）</td></tr></tbody></table><p>控制程序应以 <code>onero-sdk</code> 中 A1R/A1L URDF 的弧度限位为准，角度值仅为近似换算。A1R 与 A1L 的 J1、J2 为镜像范围，J3～J7 相同；其中产品说明书将 J5 标为 <code>±158°</code>，当前 SDK 模型限位为 <code>±2.23 rad</code>（约 <code>±127.8°</code>）。运行时可通过 <code>arm.get_joint_limits()</code> 读取当前型号的实际限位。API 使用方式请参阅<a href="/onerobot-A1/motion/">运动控制接口总览</a>。</p><h2 id="使用环境" tabindex="-1">使用环境 <a class="header-anchor" href="#使用环境" aria-label="Permalink to &quot;使用环境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>工作温度</td><td>5°C～50°C</td></tr><tr><td>相对湿度</td><td>RH 35～80，无结霜</td></tr><tr><td>安装方式</td><td>桌面固定或底座安装；安装面应水平、稳固并避免振动</td></tr></tbody></table><p>产品说明书列出的软件支持包括 Ubuntu 22.04 LTS、开源 Python SDK、ROS 2 Humble、MoveIt 2，以及提供 URDF 和控制器配置的 Gazebo 仿真。各项能力可能由独立软件包提供，不等于全部包含在核心 <code>onero-sdk</code> 安装中；具体边界见<a href="/onerobot-A1/integrations/">集成能力与边界</a>。</p><h2 id="参数如何用于配置" tabindex="-1">参数如何用于配置 <a class="header-anchor" href="#参数如何用于配置" aria-label="Permalink to &quot;参数如何用于配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置任务</th><th>应参考的参数</th><th>进一步检查</th></tr></thead><tbody><tr><td>选择模型</td><td>A1L/A1R 和安装方向</td><td><code>mounting</code>、左右臂映射和 CAN 通道</td></tr><tr><td>设置关节目标</td><td>运动范围和最大速度</td><td>目标是否接近限位、速度和加速度是否过高</td></tr><tr><td>设置负载</td><td>负载和重心信息</td><td>工具、工件和安装姿态的实际变化</td></tr><tr><td>配置电源与通信</td><td>电源、CAN 速率和接口</td><td>设备说明、适配器驱动和总线状态</td></tr></tbody></table><p>任何“最大”参数都不应直接作为程序默认值。首次运动应从更小的范围和更低的速度开始，并在现场确认机械支撑、工具和工作空间。</p><h2 id="单位与配置边界" tabindex="-1">单位与配置边界 <a class="header-anchor" href="#单位与配置边界" aria-label="Permalink to &quot;单位与配置边界&quot;">​</a></h2><p>技术参数表使用设备资料中常见的角度制和毫米制，而 SDK 运动接口通常使用 SI 单位。将参数写入代码前，应在输入边界完成一次明确的转换：</p><table tabindex="0"><thead><tr><th>资料中的单位</th><th>SDK 常用单位</th><th>换算</th></tr></thead><tbody><tr><td>角度 <code>deg</code></td><td>关节角 <code>rad</code></td><td><code>rad = deg × π / 180</code></td></tr><tr><td>角速度 <code>deg/s</code></td><td><code>rad/s</code></td><td><code>rad/s = deg/s × π / 180</code></td></tr><tr><td>长度 <code>mm</code></td><td><code>m</code></td><td><code>m = mm / 1000</code></td></tr><tr><td>质量 <code>g</code></td><td><code>kg</code></td><td><code>kg = g / 1000</code></td></tr></tbody></table><p>关节范围、最大速度和扭矩只能用于初步检查目标是否明显不合理，不能代替针对工具、负载、姿态和环境的轨迹验证。接近限位或最大参数的任务应在仿真和低速条件下逐步确认。</p><hr><p>本页依据《onero Robotic Arm A1 机械臂产品说明书》整理 Onero A1 的主要技术参数，供选型、安装和控制参数配置时参考。</p><p><a href="https://github.com/OpenWonderLabs/RobotDoc/tree/main/chinese/arm" target="_blank" rel="noreferrer">完整参考文件</a></p>',24)])])}const p=d(a,[["render",c]]);export{m as __pageData,p as default};
